python3 -c "
import json
from math import gcd
rows=json.load(open('factorizer_lattice/lattice.json'))
# candidate scalar readings per row
def cand(r):
    P=r['period']; C=r['cuts']; N=r['N']
    return {'P':P,'C':C,'P+C':P+C,'P-C':P-C,'P*C':P*C,'C-P':C-P,
            '2C':2*C,'P+2C':P+2*C,'P*C+P':P*C+P,'C^2':C*C,'P^2':P*P,
            'P*C-C':P*C-C,'C*(C-1)':C*(C-1),'P+C^2':P+C*C}
hits={}
for r in rows:
    N=r['N']; p=r.get('p'); 
    if not p: continue
    for k,v in cand(r).items():
        for delta in (0,1,-1):
            g=gcd(abs(v+delta),N)
            if 1<g<N:
                hits.setdefault(k+f'{delta:+d}',[]).append((N,g,p in (g,N//g)))
# report combos that give a nontrivial factor for MANY rows
print('combo : #rows_factored / total, all_correct?')
tot=sum(1 for r in rows if r.get('p'))
for k,v in sorted(hits.items(), key=lambda x:-len(x[1])):
    if len(v)>=tot//2:
        allc=all(x[2] for x in v)
        print(f'{k:10} : {len(v)}/{tot}  correct={allc}  e.g.{v[:4]}')
"

