from sympy import n_order
from math import lcm, gcd, isqrt
L={r['N']:r for r in json.load(open('factorizer_lattice/lattice.json'))}
# instant reads I have per N: period P, cuts C ; gnfs m = round(N**(1/3))
def m_of(N):
    lo=1;hi=N
    while lo<hi:
        mid=(lo+hi+1)//2
        if mid**3<=N: lo=mid
        else: hi=mid-1
    return lo
