// winding-carrier register. ⊙ seed a; ∈ open frame; ≻ ascent x*=a mod N; ⊤ record;
// ≺ CLEAR but BANK the order the instant the frame closes (x==1); ⊥⊞ the F/paradox
// arms; ∋ fuse = restore the banked order; ⊡ fix as integer invariant. Factor via
// gcd(a^(r/2)±1, N). Faithful to the weight trace; the ≺ bank is where "instant
// access" would live if the frame closed without the ascent walking to it.
use membranes::{Big, from_dec, to_dec, mul, sub, add, divmod, from_u32, cmp, is_zero};
use core::cmp::Ordering::*;
fn one()->Big{from_u32(1)}
fn mulmod(a:&Big,b:&Big,n:&Big)->Big{ divmod(&mul(a,b),n).1 }
fn gcd(a:&Big,b:&Big)->Big{ let(mut x,mut y)=(a.clone(),b.clone()); while !is_zero(&y){ let r=divmod(&x,&y).1; x=y; y=r;} x }
fn powmod(a:&Big,e:&Big,n:&Big)->Big{ let mut r=one(); let mut base=divmod(a,n).1; let mut ee=e.clone(); let two=from_u32(2);
    while !is_zero(&ee){ let(q,rem)=divmod(&ee,&two); if !is_zero(&rem){ r=mulmod(&r,&base,n);} base=mulmod(&base,&base,n); ee=q;} r }
fn main(){
    let args:Vec<String>=std::env::args().skip(1).collect();
    let n=from_dec(&args[0]);
    let cap:u64=args.iter().position(|a|a=="cap").and_then(|i|args.get(i+1)).and_then(|s|s.parse().ok()).unwrap_or(u64::MAX);
    // ⊙ seed generator a=2 (⊞ arm would hold alternatives); ∈ open frame; ≻ ascent, bank order at closure.
    let a=from_u32(2);
    let mut x=a.clone(); let mut k:u64=1; let mut banked:Option<u64>=None; let mut ticks:u64=0;
    while (k as u64) < cap {
        x=mulmod(&x,&a,&n); k+=1; ticks+=1;               // ≻ ascent
        if cmp(&x,&one())==Equal { banked=Some(k); break;} // ≺ clear→BANK the order
    }
    match banked {
        Some(r) => {                                       // ∋ restore, ⊡ fix, factor
            println!("instant_read word ⊣⊣⊙∈≻⊤≺⊥⊞⋈∋⊡");
