                    let g=gcd(&pm,&n);
                    if cmp(&g,&one())==Greater && cmp(&g,&n)==Less {
                        let (co,_)=divmod(&n,&g);
                        println!("  {} = {} x {}", to_dec(&n), to_dec(&g), to_dec(&co)); return;
