    if N <= 1 || gcd(a, N) != 1 { return None; }
    if a % N == 1 { return Some(1); }
    let m = isqrt(N) + 1;                       // the torus diameter
    let mut baby: Vec<(u64, u64)> = Vec::with_capacity(m as usize);
    let mut cur = 1u64;
    for j in 0..m {                             // one radius clockwise
        baby.push((cur, j));
        cur = mulmod(cur, a, N);
