300	    o.push_str("  dialect register : ");
301	    for &u in DIALECT_REGISTER.iter() {
302	        o.push_str(if crate::repl::dialect_all_pass(u, &ig) { "1" } else { "0" });
303	    }
304	    o.push_str(&format!("  (U{:?})", DIALECT_REGISTER));
305	    // n's own tuple was already computed above for the dialect register;
306	    // it is a real IgTuple like any other, so it has a crystal address
