/// `prime_winding` reads it, by digit encoding; this is that reading, not a
/// factoring claim.
pub fn read(n: &str) -> String {
    let dw = digit_encode(n);
    if dw.is_empty() {
        return format!("trilattice_factor read {}: not a valid non-negative integer", n);
    }
    let landings = cycle_landings(&dw);
    let mut o = format!("trilattice_factor read {}:\n", n);
    o.push_str(&format!("  hex-digit word   : {}\n", dw));
    match landings {
        Some(l) => {
            let commits = l.iter().filter(|r| r.as_str() == "T").count();
            o.push_str(&format!(
                "  period {}, {} winding-commit cut(s) over the orbit\n",
                l.len(), commits
            ));
        }
        None => o.push_str("  no IMASM glyphs in the digit word\n"),
    }
    // The native parity-graded word: bijective with n, where the hex word is
    // not. This is the mapping the Native IMASM-Numeral Mapping ob3ect gives.
    let nw = native_encode(n);
    o.push_str(&format!("  native word      : {}\n", nw));
    // DIALECT_REGISTER: n's own tuple checked against the 12 dialects whose
    // gate-pass sequence reaches the true order where parity alone can fall
    // short (see module doc comment). One bit per dialect, PASS/FAIL on n's
    // own word, not on a residue cycle — the register `dialect-probe` sweeps
    // for order-finding, read here on n directly.
    let ig = crate::axis_values::word_to_tuple(&nw);
    o.push_str("  dialect register : ");
    for &u in DIALECT_REGISTER.iter() {
        o.push_str(if crate::repl::dialect_all_pass(u, &ig) { "1" } else { "0" });
    }
    o.push_str(&format!("  (U{:?})", DIALECT_REGISTER));
    // n's own tuple was already computed above for the dialect register;
    // it is a real IgTuple like any other, so it has a crystal address
    // the same way every Imscription does -- of(17,280,000), not of n's
    // own magnitude. n's word folds down to this one 12-axis state no
    // matter how large n is, the same compression a hash gives, so many
    // different n share an address; the address names which of the
    // 17,280,000 structural types n's word resolves to, not which number
    // n is.
    o.push_str(&format!("\n  crystal address  : {} of {}", ig.crystal_address(), crate::crystal::TOTAL));
    o
}

